,"created_at":"2025-10-16 06:31:06","updated_at":"2025-10-19 14:28:37","original_name":"Detonating Illusionist","original_rarity":"Legendary","original_element":"N\/A"}];
        let filteredData = [...originalData];
        
        // Pagination variables
        let currentPage = 1;
        let pageSize = 100;
        let totalPages = 1;

        // Column visibility - handled by PHP
        const visibleColumns = {
            id: true,
            success: true,
            name: true,
            level: true,
            rarity: true,
            manufacturer: true,
            type: true,
            element: true,
            parts: true,
            serial: true,
            raw: true        };
        
        // Settings management
        let settingsOpen = false;
        
        function toggleSettings() {
            const panel = document.getElementById('settingsPanel');
            settingsOpen = !settingsOpen;
            
            if (settingsOpen) {
                panel.classList.add('open');
                loadSettings();
                populateColumnList();
            } else {
                panel.classList.remove('open');
            }
        }
        
        function loadSettings() {
            // Load theme
            const theme = localStorage.getItem('theme') || 'light';
            document.querySelector(`input[name="theme"][value="${theme}"]`).checked = true;
            document.body.className = theme === 'dark' ? 'dark-mode' : '';
            
            // Load colors
            document.getElementById('textColor').value = localStorage.getItem('textColor') || '#333333';
            document.getElementById('partsColor').value = localStorage.getItem('partsColor') || '#32cd32';
            document.getElementById('bgColor').value = localStorage.getItem('bgColor') || '#ffffff';
        }
        
        function populateColumnList() {
            const columnList = document.getElementById('columnList');
            const columns = [
                { key: 'id', name: 'ID' },
                { key: 'success', name: 'Success' },
                { key: 'name', name: 'Name' },
                { key: 'level', name: 'Level' },
                { key: 'rarity', name: 'Rarity' },
                { key: 'manufacturer', name: 'Manufacturer' },
                { key: 'type', name: 'Type' },
                { key: 'element', name: 'Element' },
                { key: 'parts', name: 'Parts' },
                { key: 'serial', name: 'Serial' },
                { key: 'raw', name: 'Raw Data' }
            ];
            
            columnList.innerHTML = '';
            columns.forEach(column => {
                const item = document.createElement('div');
                item.className = 'column-item';
                item.innerHTML = `
                    <input type="checkbox" ${visibleColumns[column.key] ? 'checked' : ''} onchange="toggleColumnVisibility('${column.key}')">
                    <span>${column.name}</span>
                `;
                columnList.appendChild(item);
            });
        }
        
        function toggleColumnVisibility(columnKey) {
            visibleColumns[columnKey] = !visibleColumns[columnKey];
        }
        
        function saveSettings() {
            // Save theme
            const theme = document.querySelector('input[name="theme"]:checked').value;
            localStorage.setItem('theme', theme);
            document.body.className = theme === 'dark' ? 'dark-mode' : '';
            
            // Save colors
            localStorage.setItem('textColor', document.getElementById('textColor').value);
            localStorage.setItem('partsColor', document.getElementById('partsColor').value);
            localStorage.setItem('bgColor', document.getElementById('bgColor').value);
            
            // Save column configuration
            localStorage.setItem('columnConfig', JSON.stringify(visibleColumns));
            
            // Apply color changes
            applyColorSettings();
            
            // Close settings panel
            toggleSettings();
            
            // Reload page to apply column changes
            window.location.reload();
        }
        
        function resetSettings() {
            localStorage.removeItem('theme');
            localStorage.removeItem('textColor');
            localStorage.removeItem('partsColor');
            localStorage.removeItem('bgColor');
            localStorage.removeItem('columnConfig');
            
            // Reset to defaults
            document.querySelector('input[name="theme"][value="light"]').checked = true;
            document.getElementById('textColor').value = '#333333';
            document.getElementById('partsColor').value = '#32cd32';
            document.getElementById('bgColor').value = '#ffffff';
            
            // Reset column visibility
            Object.keys(visibleColumns).forEach(key => {
                visibleColumns[key] = true;
            });
            
            populateColumnList();
        }
        
        function applyColorSettings() {
            const textColor = localStorage.getItem('textColor') || '#333333';
            const partsColor = localStorage.getItem('partsColor') || '#32cd32';
            const bgColor = localStorage.getItem('bgColor') || '#ffffff';
            
            document.documentElement.style.setProperty('--text-color', textColor);
            document.documentElement.style.setProperty('--parts-color', partsColor);
            document.documentElement.style.setProperty('--bg-color', bgColor);
        }
        
        function toggleColumn(columnName) {
            const checkbox = event.target;
            const columnIndex = getColumnIndex(columnName);
            const headers = document.querySelectorAll('th');
            const cells = document.querySelectorAll(`td:nth-child(${columnIndex + 1})`);
            
            if (checkbox.checked) {
                visibleColumns[columnName] = true;
                localStorage.setItem('col_' + columnName, 'true');
                headers[columnIndex].classList.remove('hidden-column');
                cells.forEach(cell => {
                    cell.classList.remove('hidden-column');
                    // Restore content if it was stored
                    if (cell.dataset.originalContent) {
                        cell.innerHTML = cell.dataset.originalContent;
                        delete cell.dataset.originalContent;
                    }
                });
            } else {
                visibleColumns[columnName] = false;
                localStorage.setItem('col_' + columnName, 'false');
                headers[columnIndex].classList.add('hidden-column');
                cells.forEach(cell => {
                    cell.classList.add('hidden-column');
                    // Store original content and clear it
                    if (!cell.dataset.originalContent) {
                        cell.dataset.originalContent = cell.innerHTML;
                        cell.innerHTML = '';
                    }
                });
            }
            
            // Smart column width adjustment
            adjustColumnWidths();
            
            // Adjust row heights after column changes
            setTimeout(() => {
                adjustRowHeights();
            }, 50);
        }
        
        function reapplyHiddenColumns() {
            Object.keys(visibleColumns).forEach(columnName => {
                if (!visibleColumns[columnName]) {
                    const columnIndex = getColumnIndex(columnName);
                    const headers = document.querySelectorAll('th');
                    const cells = document.querySelectorAll(`td:nth-child(${columnIndex + 1})`);
                    
                    headers[columnIndex].classList.add('hidden-column');
                    cells.forEach(cell => {
                        cell.classList.add('hidden-column');
                        // Store original content and clear it
                        if (!cell.dataset.originalContent) {
                            cell.dataset.originalContent = cell.innerHTML;
                            cell.innerHTML = '';
                        }
                    });
                }
            });
        }
        
        function adjustRowHeights() {
            const rows = document.querySelectorAll('tbody tr');
            const hasHiddenColumns = document.querySelectorAll('.hidden-column').length > 0;
            
            rows.forEach(row => {
                // Remove any existing compact-row class
                row.classList.remove('compact-row');
                
                if (hasHiddenColumns) {
                    const cells = row.querySelectorAll('td:not(.hidden-column)');
                    let maxHeight = 30; // Minimum height
                    let hasLongContent = false;
                    
                    cells.forEach(cell => {
                        // Force recalculation by temporarily removing height
                        const originalHeight = cell.style.height;
                        cell.style.height = 'auto';
                        
                        // Calculate content height
                        const contentHeight = cell.scrollHeight;
                        if (contentHeight > maxHeight) {
                            maxHeight = contentHeight;
                        }
                        
                        // Check if this cell has long content (more than 2 lines)
                        if (contentHeight > 50) {
                            hasLongContent = true;
                        }
                        
                        // Restore original height
                        cell.style.height = originalHeight;
                    });
                    
                    // Only apply compact-row if there are hidden columns AND long content
                    if (hasLongContent && maxHeight > 40) {
                        row.classList.add('compact-row');
                    } else {
                        // Let the row grow naturally
                        row.style.height = maxHeight + 'px';
                    }
                } else {
                    // No hidden columns, let rows grow naturally
                    const cells = row.querySelectorAll('td');
                    let maxHeight = 30;
                    
                    cells.forEach(cell => {
                        const contentHeight = cell.scrollHeight;
                        if (contentHeight > maxHeight) {
                            maxHeight = contentHeight;
                        }
                    });
                    
                    row.style.height = maxHeight + 'px';
                }
            });
        }
        
        function adjustColumnWidths() {
            // Define which columns can expand (Parts, Serial, Raw Data)
            const expandableColumns = [8, 9, 10]; // Parts, Serial, Raw Data (0-indexed)
            
            // Reset all widths to CSS defaults
            for (let i = 1; i <= 13; i++) {
                const elements = document.querySelectorAll(`th:nth-child(${i}), td:nth-child(${i})`);
                elements.forEach(el => el.style.width = '');
            }
            
            // Calculate freed space from hidden columns
            const hiddenColumns = [];
            const headers = document.querySelectorAll('th');
            headers.forEach((header, index) => {
                if (header.classList.contains('hidden-column')) {
                    hiddenColumns.push(index);
                }
            });
            
            // If Raw Data (column 10) is hidden, give its space to Parts (column 8)
            if (hiddenColumns.includes(10)) { // Raw Data hidden
                const partsElements = document.querySelectorAll(`th:nth-child(9), td:nth-child(9)`); // Parts column
                partsElements.forEach(el => el.style.width = '30%'); // Give Parts more space
            }
            
            // If Serial (column 9) is hidden, give its space to Parts (column 8)  
            if (hiddenColumns.includes(9)) { // Serial hidden
                const partsElements = document.querySelectorAll(`th:nth-child(9), td:nth-child(9)`); // Parts column
                partsElements.forEach(el => el.style.width = '33%'); // Give Parts even more space
            }
        }

        function getColumnIndex(columnName) {
            const columnMap = {
                'id': 0, 'success': 1, 'name': 2, 'level': 3, 'rarity': 4,
                'manufacturer': 5, 'type': 6, 'element': 7, 'parts': 8,
                'serial': 9, 'raw': 10
            };
            return columnMap[columnName] || 0;
        }

        // Filtering functions
        function applyFilters() {
            const globalSearch = document.getElementById('globalSearch').value.toLowerCase();
            const serialFilter = document.getElementById('serialFilter').value.toLowerCase();
            const manufacturerFilter = document.getElementById('manufacturerFilter').value;
            const typeFilter = document.getElementById('typeFilter').value;
            const elementFilter = document.getElementById('elementFilter').value;
            const rarityFilter = document.getElementById('rarityFilter').value;
            const levelMin = parseInt(document.getElementById('levelMinFilter').value) || 0;
            const levelMax = parseInt(document.getElementById('levelMaxFilter').value) || 999;
            const partFilter = document.getElementById('partFilter').value.toLowerCase();

            filteredData = originalData.filter(item => {
                // Global search across visible columns only
                if (globalSearch) {
                    let searchableText = '';
                    
                    // Build searchable text based on visible columns
                    if (visibleColumns.name && item.original_name) {
                        searchableText += item.original_name.toLowerCase() + ' ';
                    }
                    if (visibleColumns.rarity && item.original_rarity) {
                        searchableText += item.original_rarity.toLowerCase() + ' ';
                    }
                    if (visibleColumns.manufacturer && item.deserialized_manufacturer) {
                        searchableText += item.deserialized_manufacturer.toLowerCase() + ' ';
                    }
                    if (visibleColumns.type && item.deserialized_type) {
                        searchableText += item.deserialized_type.toLowerCase() + ' ';
                    }
                    if (visibleColumns.element && item.original_element) {
                        searchableText += item.original_element.toLowerCase() + ' ';
                    }
                    if (visibleColumns.parts && item.deserialized_parts) {
                        searchableText += item.deserialized_parts.toLowerCase() + ' ';
                    }
                    if (visibleColumns.serial && item.serial_b85) {
                        searchableText += item.serial_b85.toLowerCase() + ' ';
                    }
                    if (visibleColumns.raw && item.deserialized_raw) {
                        searchableText += item.deserialized_raw.toLowerCase() + ' ';
                    }
                    
                    // Check if all search terms are found in the combined text
                    const searchTerms = globalSearch.split(' ').filter(term => term.length > 0);
                    const allTermsFound = searchTerms.every(term => {
                        // Use word boundary regex to avoid partial matches
                        const regex = new RegExp(`\\b${term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i');
                        return regex.test(searchableText);
                    });
                    
                    if (!allTermsFound) return false;
                }

                // Serial filter (only if serial column is visible)
                if (serialFilter && visibleColumns.serial && !item.serial_b85.toLowerCase().includes(serialFilter)) {
                    return false;
                }

                // Manufacturer filter (only if manufacturer column is visible)
                if (manufacturerFilter && visibleColumns.manufacturer && item.deserialized_manufacturer !== manufacturerFilter) {
                    return false;
                }

                // Type filter (only if type column is visible)
                if (typeFilter && visibleColumns.type && item.deserialized_type !== typeFilter) {
                    return false;
                }

                // Element filter (only if element column is visible)
                if (elementFilter && visibleColumns.element && item.original_element !== elementFilter) {
                    return false;
                }

                // Rarity filter (only if rarity column is visible)
                if (rarityFilter && visibleColumns.rarity && item.original_rarity !== rarityFilter) {
                    return false;
                }

                // Level filter (only if level column is visible)
                if (visibleColumns.level) {
                const level = parseInt(item.deserialized_level) || 0;
                if (level < levelMin || level > levelMax) {
                    return false;
                    }
                }

                // Part filter (only if parts column is visible)
                if (partFilter && visibleColumns.parts) {
                    const parts = item.deserialized_parts ? JSON.parse(item.deserialized_parts) : [];
                    const hasPart = parts.some(part => part.toLowerCase().includes(partFilter));
                    if (!hasPart) return false;
                }

                return true;
            });

            // Reset to first page when filtering
            currentPage = 1;
            updateTable();
        }

        function updateTable() {
            // Calculate pagination
            totalPages = Math.ceil(filteredData.length / pageSize);
            if (currentPage > totalPages) currentPage = totalPages;
            if (currentPage < 1) currentPage = 1;

            // Get current page data
            const startIndex = (currentPage - 1) * pageSize;
            const endIndex = startIndex + pageSize;
            const currentPageData = filteredData.slice(startIndex, endIndex);

            const tbody = document.querySelector('tbody');
            tbody.innerHTML = '';

            currentPageData.forEach(item => {
                const row = document.createElement('tr');
                
                // Parse parts for display
                let partsHtml = '-';
                if (item.deserialized_parts) {
                    const parts = JSON.parse(item.deserialized_parts);
                    if (Array.isArray(parts)) {
                        partsHtml = parts.map(part => `<span class="part">${part}</span>`).join('');
                    } else {
                        partsHtml = item.deserialized_parts;
                    }
                }

                let rowHtml = '';
                
                if (visibleColumns.id) {
                    rowHtml += `<td>${item.id}</td>`;
                }
                if (visibleColumns.success) {
                    rowHtml += `<td>${item.success ? '<span class="success">✓</span>' : '<span class="failed">✗</span>'}</td>`;
                }
                if (visibleColumns.name) {
                    rowHtml += `<td><span class="manufacturer">${item.original_name || '-'}</span></td>`;
                }
                if (visibleColumns.level) {
                    rowHtml += `<td>${item.deserialized_level ? `<span class="level">${item.deserialized_level}</span>` : '-'}</td>`;
                }
                if (visibleColumns.rarity) {
                    rowHtml += `<td>${item.original_rarity ? `<span class="rarity ${item.original_rarity.toLowerCase()}">${item.original_rarity}</span>` : '-'}</td>`;
                }
                if (visibleColumns.manufacturer) {
                    rowHtml += `<td><span class="manufacturer">${item.deserialized_manufacturer || '-'}</span></td>`;
                }
                if (visibleColumns.type) {
                    rowHtml += `<td>${item.deserialized_type ? `<span class="type">${item.deserialized_type}</span>` : '-'}</td>`;
                }
                if (visibleColumns.element) {
                    rowHtml += `<td>${item.original_element ? `<span class="element ${item.original_element.toLowerCase()}">${item.original_element}</span>` : '-'}</td>`;
                }
                if (visibleColumns.parts) {
                    rowHtml += `<td class="parts">${partsHtml}</td>`;
                }
                if (visibleColumns.serial) {
                    rowHtml += `<td class="serial" onclick="copySerial('${item.serial_b85.replace(/'/g, "\\'")}')" title="${item.serial_b85.replace(/"/g, '&quot;')}">${item.serial_b85.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</td>`;
                }
                if (visibleColumns.raw) {
                    rowHtml += `<td class="serial">${(item.deserialized_raw || '-').replace(/</g, '&lt;').replace(/>/g, '&gt;')}</td>`;
                }
                
                row.innerHTML = rowHtml;
                tbody.appendChild(row);
            });

            // Update record count
            document.querySelector('.status-info span:nth-child(2)').textContent = `Records: ${filteredData.length.toLocaleString()}`;
            
            // Update pagination controls
            updatePaginationControls();
        }

        function updatePaginationControls() {
            // Update pagination info
            const startRecord = (currentPage - 1) * pageSize + 1;
            const endRecord = Math.min(currentPage * pageSize, filteredData.length);
            document.getElementById('paginationInfo').textContent = 
                `Showing ${startRecord}-${endRecord} of ${filteredData.length.toLocaleString()} records`;

            // Adjust row heights after table update
            setTimeout(() => {
                adjustRowHeights();
            }, 100);

            // Update page numbers
            const pageNumbersDiv = document.getElementById('pageNumbers');
            pageNumbersDiv.innerHTML = '';

            // Show max 5 page numbers around current page
            const maxVisiblePages = 5;
            let startPage = Math.max(1, currentPage - Math.floor(maxVisiblePages / 2));
            let endPage = Math.min(totalPages, startPage + maxVisiblePages - 1);

            if (endPage - startPage + 1 < maxVisiblePages) {
                startPage = Math.max(1, endPage - maxVisiblePages + 1);
            }

            for (let i = startPage; i <= endPage; i++) {
                const button = document.createElement('button');
                button.textContent = i;
                button.onclick = () => goToPage(i);
                if (i === currentPage) {
                    button.classList.add('active');
                }
                pageNumbersDiv.appendChild(button);
            }

            // Update navigation buttons
            document.getElementById('firstBtn').disabled = currentPage === 1;
            document.getElementById('prevBtn').disabled = currentPage === 1;
            document.getElementById('nextBtn').disabled = currentPage === totalPages;
            document.getElementById('lastBtn').disabled = currentPage === totalPages;
        }

        function goToPage(page) {
            if (page >= 1 && page <= totalPages) {
                currentPage = page;
                updateTable();
            }
        }

        function changePageSize() {
            pageSize = parseInt(document.getElementById('pageSize').value);
            currentPage = 1; // Reset to first page
            updateTable();
        }

        function clearFilters() {
            document.getElementById('globalSearch').value = '';
            document.getElementById('serialFilter').value = '';
            document.getElementById('manufacturerFilter').value = '';
            document.getElementById('typeFilter').value = '';
            document.getElementById('elementFilter').value = '';
            document.getElementById('rarityFilter').value = '';
            document.getElementById('levelMinFilter').value = '';
            document.getElementById('levelMaxFilter').value = '';
            document.getElementById('partFilter').value = '';
            applyFilters();
        }

        // Copy serial function to prevent encoding issues
        function copySerial(serial) {
            // Create a temporary textarea to copy the serial without encoding issues
            const textarea = document.createElement('textarea');
            textarea.value = serial;
            textarea.style.position = 'fixed';
            textarea.style.opacity = '0';
            document.body.appendChild(textarea);
            textarea.select();
            textarea.setSelectionRange(0, 99999); // For mobile devices
            
            try {
                document.execCommand('copy');
                // Show a brief success message
                const originalText = event.target.textContent;
                event.target.textContent = 'Copied!';
                event.target.style.backgroundColor = '#d4edda';
                setTimeout(() => {
                    event.target.textContent = originalText;
                    event.target.style.backgroundColor = '';
                }, 1000);
            } catch (err) {
                console.error('Failed to copy serial:', err);
            }
            
            document.body.removeChild(textarea);
        }

        // Copy all serials function
        function copyAllSerials() {
            const allSerials = filteredData.map(item => item.serial_b85).join('\n');
            
            // Create a temporary textarea to copy all serials without encoding issues
            const textarea = document.createElement('textarea');
            textarea.value = allSerials;
            textarea.style.position = 'fixed';
            textarea.style.opacity = '0';
            document.body.appendChild(textarea);
            textarea.select();
            textarea.setSelectionRange(0, 99999); // For mobile devices
            
            try {
                document.execCommand('copy');
                alert(`Copied ${filteredData.length} serials to clipboard!`);
            } catch (err) {
                console.error('Failed to copy serials:', err);
                alert('Failed to copy serials. Please try again.');
            }
            
            document.body.removeChild(textarea);
        }

        // Add event listeners
        document.addEventListener('DOMContentLoaded', function() {
            document.getElementById('globalSearch').addEventListener('input', applyFilters);
            document.getElementById('serialFilter').addEventListener('input', applyFilters);
            document.getElementById('manufacturerFilter').addEventListener('change', applyFilters);
            document.getElementById('typeFilter').addEventListener('change', applyFilters);
            document.getElementById('elementFilter').addEventListener('change', applyFilters);
            document.getElementById('rarityFilter').addEventListener('change', applyFilters);
            document.getElementById('levelMinFilter').addEventListener('input', applyFilters);
            document.getElementById('levelMaxFilter').addEventListener('input', applyFilters);
            document.getElementById('partFilter').addEventListener('input', applyFilters);
            
            // Load saved settings
            loadSettings();
            applyColorSettings();
            
            // Initialize the table with first page
            updateTable();
        });
    </script>
